mapper.select:
/* BizHourMapper.getDaysPivotList */ SELECT b.STORE_CD, b.STORE_NM, b.OWNER_NM, b.SYS_STAT_FG, b.SEQ
, MAX(CASE WHEN d.DAY_FG = '1' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_SUN , MAX(CASE WHEN d.DAY_FG = '1' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_SUN , MAX(CASE WHEN d.DAY_FG = '1' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_SUN , MAX(CASE WHEN d.DAY_FG = '1' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_SUN , MAX(CASE WHEN d.DAY_FG = '2' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_MON , MAX(CASE WHEN d.DAY_FG = '2' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_MON , MAX(CASE WHEN d.DAY_FG = '2' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_MON , MAX(CASE WHEN d.DAY_FG = '2' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_MON , MAX(CASE WHEN d.DAY_FG = '3' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_TUE , MAX(CASE WHEN d.DAY_FG = '3' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_TUE , MAX(CASE WHEN d.DAY_FG = '3' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_TUE , MAX(CASE WHEN d.DAY_FG = '3' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_TUE , MAX(CASE WHEN d.DAY_FG = '4' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_WED , MAX(CASE WHEN d.DAY_FG = '4' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_WED , MAX(CASE WHEN d.DAY_FG = '4' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_WED , MAX(CASE WHEN d.DAY_FG = '4' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_WED , MAX(CASE WHEN d.DAY_FG = '5' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_THU , MAX(CASE WHEN d.DAY_FG = '5' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_THU , MAX(CASE WHEN d.DAY_FG = '5' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_THU , MAX(CASE WHEN d.DAY_FG = '5' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_THU , MAX(CASE WHEN d.DAY_FG = '6' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_FRI , MAX(CASE WHEN d.DAY_FG = '6' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_FRI , MAX(CASE WHEN d.DAY_FG = '6' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_FRI , MAX(CASE WHEN d.DAY_FG = '6' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_FRI , MAX(CASE WHEN d.DAY_FG = '7' THEN SUBSTR(d.START_TIME,1,2) END) AS START_HOUR_SAT , MAX(CASE WHEN d.DAY_FG = '7' THEN SUBSTR(d.START_TIME,3,2) END) AS START_MS_SAT , MAX(CASE WHEN d.DAY_FG = '7' THEN SUBSTR(d.END_TIME,1,2) END) AS END_HOUR_SAT , MAX(CASE WHEN d.DAY_FG = '7' THEN SUBSTR(d.END_TIME,3,2) END) AS END_MS_SAT
FROM ( SELECT s.STORE_CD, s.STORE_NM, s.OWNER_NM, s.SYS_STAT_FG, q.SEQ FROM TB_MS_STORE s , ( SELECT LEVEL AS SEQ FROM DUAL CONNECT BY LEVEL <= ( SELECT NVL(MAX(SEQ), 1) FROM TB_MS_STORE_BIZHOUR_DAYS WHERE HQ_OFFICE_CD = #{hqOfficeCd}
AND STORE_CD IN (${storeCdQuery})
) ) q WHERE s.HQ_OFFICE_CD = #{hqOfficeCd}
AND s.STORE_CD IN (${storeCdQuery})
) b , TB_MS_STORE_BIZHOUR_DAYS d WHERE d.HQ_OFFICE_CD(+) = #{hqOfficeCd} AND d.STORE_CD(+) = b.STORE_CD AND d.SEQ(+) = b.SEQ GROUP BY b.STORE_CD, b.STORE_NM, b.OWNER_NM, b.SYS_STAT_FG, b.SEQ HAVING b.SEQ = 1 OR COUNT(d.STORE_CD) > 0 ORDER BY b.STORE_CD, b.SEQ

/* BizHourMapper.getDaysOverlapCnt */
SELECT  COUNT(*)
FROM    TB_MS_STORE_BIZHOUR_DAYS
WHERE   HQ_OFFICE_CD    =   #{hqOfficeCd}
AND     STORE_CD        =   #{storeCd}
AND     DAY_FG          =   #{dayFg}

AND     START_TIME      <   #{endTime}
AND     END_TIME        >   #{startTime}


    AND SEQ NOT IN
    #{exSeq}


    AND SEQ != #{seq}

/* BizHourMapper.getDaysMaxSeq */
SELECT  NVL(MAX(SEQ), 0) + 1
FROM    TB_MS_STORE_BIZHOUR_DAYS
WHERE   HQ_OFFICE_CD    =   #{hqOfficeCd}
AND     STORE_CD        =   #{storeCd}
AND     DAY_FG          =   #{dayFg}

