mapper.insert:
/* BizHourMapper.copyDaysToStore */
INSERT INTO TB_MS_STORE_BIZHOUR_DAYS
(
    HQ_OFFICE_CD, STORE_CD, DAY_FG, SEQ, START_TIME, END_TIME,
    REG_DT, REG_ID, MOD_DT, MOD_ID
)
SELECT  #{hqOfficeCd}, t.STORE_CD, s.DAY_FG, s.SEQ, s.START_TIME, s.END_TIME,
        #{modDt}, #{modId}, #{modDt}, #{modId}
FROM    TB_MS_STORE_BIZHOUR_DAYS s
,       (
            SELECT  STORE_CD
            FROM    TB_MS_STORE
            WHERE   HQ_OFFICE_CD = #{hqOfficeCd}
            AND     STORE_CD IN (${copyStoreCdQuery})
        ) t
WHERE   s.HQ_OFFICE_CD  = #{hqOfficeCd}
AND     s.STORE_CD      = #{storeCd}

mapper.delete:
/* BizHourMapper.deleteSpecificByCopyStore */
DELETE  TB_MS_STORE_BIZHOUR_SPECIFIC
WHERE   HQ_OFFICE_CD    = #{hqOfficeCd}
AND     STORE_CD        IN (${copyStoreCdQuery})

mapper.insert:
/* BizHourMapper.copySpecificToStore */
INSERT INTO TB_MS_STORE_BIZHOUR_SPECIFIC
(
    HQ_OFFICE_CD, STORE_CD, BIZ_DATE, SEQ, BIZ_FG, START_TIME, END_TIME, REMARK,
    REG_DT, REG_ID, MOD_DT, MOD_ID
)
SELECT  #{hqOfficeCd}, t.STORE_CD, s.BIZ_DATE, s.SEQ, s.BIZ_FG, s.START_TIME, s.END_TIME, s.REMARK,
        #{modDt}, #{modId}, #{modDt}, #{modId}
FROM    TB_MS_STORE_BIZHOUR_SPECIFIC s
,       (
            SELECT  STORE_CD
            FROM    TB_MS_STORE
            WHERE   HQ_OFFICE_CD = #{hqOfficeCd}
            AND     STORE_CD IN (${copyStoreCdQuery})
        ) t
WHERE   s.HQ_OFFICE_CD  = #{hqOfficeCd}
AND     s.STORE_CD      = #{storeCd}

mapper.select:
/* BizHourMapper.getStoreUseYn */
SELECT  NVL((
            SELECT  ENVST_VAL
            FROM    TB_MS_STORE_ENVST
            WHERE   STORE_CD = #{storeCd}
            AND     ENVST_CD = '1361'
            AND     USE_YN   = 'Y'
        ), '0')
FROM    DUAL

/* BizHourMapper.getStoreUseYnList */ SELECT s.STORE_CD, s.STORE_NM, s.OWNER_NM, s.SYS_STAT_FG , NVL(e.ENVST_VAL, '0') AS ENVST_VAL FROM TB_MS_STORE s , TB_MS_STORE_ENVST e WHERE s.HQ_OFFICE_CD = #{hqOfficeCd} AND e.STORE_CD(+) = s.STORE_CD AND e.ENVST_CD(+) = '1361' AND e.USE_YN(+) = 'Y'
AND NVL(e.ENVST_VAL, '0') = #{envstVal}
AND s.STORE_CD LIKE '%' || #{searchStoreCd} || '%'
AND s.STORE_NM LIKE '%' || #{searchStoreNm} || '%'
ORDER BY s.STORE_CD
